import csv
import sys
from statistics import mean, median

def is_float(value):
    try:
        float(value)
        return True
    except ValueError:
        return False

def main(filename):
    with open(filename, newline='') as csvfile:
        reader = csv.DictReader(csvfile)
        data = list(reader)

    if not data:
        print("CSV file is empty")
        return

    # find numeric columns
    numeric_columns = []
    for col in data[0].keys():
        if all(is_float(row[col]) for row in data if row[col] != ''):
            numeric_columns.append(col)

    # gather numeric data
    stats = {}
    for col in numeric_columns:
        values = [float(row[col]) for row in data if row[col] != '']
        stats[col] = {'mean': mean(values), 'median': median(values)}

    # print results
    for col, stat in stats.items():
        print(f"{col}: mean={stat['mean']}, median={stat['median']}")

if __name__ == '__main__':
    if len(sys.argv) < 2:
        print("Usage: python csvstats.py <csvfile>")
        sys.exit(1)
    main(sys.argv[1])
EOF

